grid = [[4]*19 for _ in range(16)]
zeros=[(2,5),(2,14),(3,1),(3,10),(5,17),(7,3),(7,13),(8,10),(10,6),(12,16),(13,10),(14,7)]
# Original template at top-left (12,2), with empty positions transparent
template={(0,0):8,(0,1):8,(0,2):2,(1,1):9,(1,2):2,(2,1):9,(2,2):9}
for (dr,dc),v in template.items(): grid[12+dr][2+dc]=v
for r,c in zeros: grid[r][c]=0
for r,c in zeros:
    for (dr,dc),v in template.items():
        rr,cc=r+dr-1,c+dc-1
        if 0<=rr<16 and 0<=cc<19:
            grid[rr][cc]=v
print('\n'.join(' '.join(map(str,row)) for row in grid))
print(zeros)
